  e=t.get(\"expiry_time\",-1); c=t.get(\"creation_time\")
  f=lambda ms: \"never\" if ms in (-1,None) else d.datetime.fromtimestamp(ms/1000,d.timezone.utc).strftime(\"%Y-%m-%d\")
  print(f\"  {t.get(\"comment\") or \"(no comment)\":40.40} created {f(c)}  expires {f(e)}\")"
