import sys,json; j=json.load(sys.stdin)
for w in j.get(\"warehouses\",[]): print(\"  \",w[\"id\"],w[\"name\"],w[\"state\"], (w.get(\"health\") or {}).get(\"status\"))
if \"warehouses\" not in j: print(\"ERR\", j.get(\"error_code\"), j.get(\"message\"))"'

